import type { CSSProperties } from "react"
import "./card-orbit.css"

const DEFAULT_IMAGES = [
  "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=300&q=80",
  "https://images.unsplash.com/photo-1519681393784-d120267933ba?w=300&q=80",
  "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe8f?w=300&q=80",
  "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=300&q=80",
  "https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?w=300&q=80",
  "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=300&q=80",
]

interface CardOrbitProps {
  images?: string[]
  /** Cor em formato "r,g,b" usada na borda e no tint do gradiente. */
  colorCard?: string
  className?: string
}

function CardOrbit({
  images = DEFAULT_IMAGES,
  colorCard = "99,102,241",
  className = "",
}: CardOrbitProps) {
  return (
    <div
      className={`card-orbit ${className}`}
      style={{ "--color-card": colorCard } as CSSProperties}
    >
      <div
        className="card-orbit__inner"
        style={{ "--quantity": images.length } as CSSProperties}
      >
        {images.map((img, index) => (
          <div
            key={index}
            className="card-orbit__card"
            style={{ "--index": index } as CSSProperties}
          >
            <div
              className="card-orbit__img"
              style={{ "--img": `url(${img})` } as CSSProperties}
            />
          </div>
        ))}
      </div>
    </div>
  )
}

export { CardOrbit }

/* classes renomeadas com prefixo card-orbit para evitar colisao com nomes genericos tipo .wrapper/.inner/.card/.img */
.card-orbit {
  width: 500px;
  max-width: 100%;
  height: 350px;
  position: relative;
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.card-orbit__inner {
  --w: 100px;
  --h: 150px;
  --translateZ: calc((var(--w) + var(--h)) + 0px);
  --rotateX: -15deg;
  --perspective: 1000px;
  position: absolute;
  width: var(--w);
  height: var(--h);
  top: 25%;
  left: calc(50% - (var(--w) / 2) - 2.5px);
  z-index: 2;
  transform-style: preserve-3d;
  transform: perspective(var(--perspective));
  animation: card-orbit-rotating 20s linear infinite;
}
@keyframes card-orbit-rotating {
  from {
    transform: perspective(var(--perspective)) rotateX(var(--rotateX))
      rotateY(0);
  }
  to {
    transform: perspective(var(--perspective)) rotateX(var(--rotateX))
      rotateY(1turn);
  }
}

.card-orbit__card {
  position: absolute;
  border: 2px solid rgba(var(--color-card));
  border-radius: 12px;
  overflow: hidden;
  inset: 0;
  transform: rotateY(calc((360deg / var(--quantity)) * var(--index)))
    translateZ(var(--translateZ));
}

.card-orbit__img {
  width: 100%;
  height: 100%;
  background-image: var(--img, none),
    radial-gradient(
      circle,
      rgba(var(--color-card), 0.2) 0%,
      rgba(var(--color-card), 0.6) 80%,
      rgba(var(--color-card), 0.9) 100%
    );
  background-size: cover, cover;
  background-position: center, center;
  background-repeat: no-repeat, no-repeat;
}
